"""TLA 3-in-1 test: pset (predicate set by pattern) exact bits.

pset(elem_width, dist) builds an ave.hir.pge with the given pattern; the
result is materialized to u32 0/1 lanes through vsel before storing.

Stages: ir (offline HIVM), compile (kernel artifacts), run (numerics).
Rows: 0 PAT.ALL (64 lanes true), 1 PAT.VL32, 2 PAT.M4, 3 PAT.ALLF.
"""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import torch
import triton
import triton.language as tl
import triton.language.extra.tla as tla
from utils.tla_test_utils import (get_stages, compile_offline, lower_offline, check_lowered_ir, check_compile_artifacts)

SHAPE = dict(lanes=64)
SIGNATURE = {"O": "*u32"}


@tla.jit
def pset(O, N: tl.constexpr):
    o = tla.alloc_buffer((4, N), tl.uint32, space="ub")
    with tla.scope.simd():
        ones = tla.simd.vsplat(1, tl.uint32)
        zeros = tla.simd.vsplat(0, tl.uint32)
        tla.simd.vsts(o[0, 0], tla.simd.vsel(tla.simd.pset(32, tla.simd.PAT.ALL), ones, zeros))
        tla.simd.vsts(o[1, 0], tla.simd.vsel(tla.simd.pset(32, tla.simd.PAT.VL32), ones, zeros))
        tla.simd.vsts(o[2, 0], tla.simd.vsel(tla.simd.pset(32, tla.simd.PAT.M4), ones, zeros))
        tla.simd.vsts(o[3, 0], tla.simd.vsel(tla.simd.pset(32, tla.simd.PAT.ALLF), ones, zeros))
    tla.copy(o, tla.view(O, (4, N)))


def constexprs():
    return {"N": SHAPE["lanes"]}


def test_ir(output_dir=None):
    module, ctx = compile_offline(pset, SIGNATURE, constexprs(), output_dir=output_dir)
    text = str(module)
    # 4 pset pge + 4 all-true masks generated by the materializing vsplats.
    assert text.count("ave.hir.pge") == 8
    assert text.count("ave.hir.pge <VL32>") == 1
    assert text.count("ave.hir.pge <M4>") == 1
    assert text.count("ave.hir.pge <ALLF>") == 1
    text = str(lower_offline(module, ctx, output_dir=output_dir))
    check_lowered_ir(text, loads=0, stores=1, buffers=None, extra=("ave.hir.pge", ))
    print("IR PASS: pset ALL/VL32/M4/ALLF patterns")


def _launch():
    s = SHAPE
    out = torch.empty((4, s["lanes"]), dtype=torch.uint32, device="npu")
    pset[(1, )](out, **constexprs())
    torch.npu.synchronize()
    n = s["lanes"]
    idx = torch.arange(n)
    ref = torch.zeros((4, n), dtype=torch.int64)
    ref[0] = 1
    ref[1] = (idx < 32).to(torch.int64)
    ref[2] = (idx % 4 == 0).to(torch.int64)
    return out, ref.to(torch.uint32)


def test_compile():
    _launch()
    artifacts = check_compile_artifacts()
    assert artifacts, "no .o/.npubin artifact in TRITON_CACHE_DIR"
    print("COMPILE PASS: pset generated artifacts", len(artifacts), "->", artifacts[0])


def test_run():
    out, ref = _launch()
    torch.testing.assert_close(out.cpu().view(torch.int32), ref.view(torch.int32), rtol=0, atol=0)
    print("PSET OK: predicate patterns exact bits")


def main():
    do_ir, do_compile, do_run = get_stages()
    if do_ir:
        test_ir()
    if do_compile:
        test_compile()
    if do_run:
        test_run()
    print("ALL PASS: pset", "ir" if do_ir else "", "compile/run" if do_run else "compile" if do_compile else "")


if __name__ == "__main__":
    main()
